import re
with open('doc/superhero.md', 'r') as f:
    content = f.read()

sections = re.split(r'\n\s*\n', content)

results = []
for i, sec in enumerate(sections):
    # Find ID - look for 'reference number X' or 'registry number X' or 'ID X' or 'identifier X'
    ids = re.findall(r'[Rr]eference[\s:]*[nN]umber[\s:]*(\d{3})', sec)
    if not ids:
        ids = re.findall(r'[Rr]egistry[\s:]*[nN]umber[\s:]*(\d{3})', sec)
    if not ids:
        ids = re.findall(r'[Ii]d[\s:]*[\(]?([\d]{3})[\)]?', sec)
    if not ids:
        ids = re.findall(r'[Ii]dentifier[\s:]*[\(]?([\d]{3})[\)]?', sec)

    # Find height
    heights = re.findall(r'[Hh]eight.*?(\d+)\.?\s*(?:cm)?', sec)

    # Find publisher - look for publisher followed by a code
    pubs = re.findall(r'[Pp]ublisher[\s:]*([A-Za-z]+)', sec)
    if not pubs:
        pubs = re.findall(r'[Pp]ublished[\s:]*[bB]y[\s:]*([A-Za-z]+)', sec)

    if ids and heights:
        for id_val in ids:
            for h in heights:
                results.append({'id': id_val, 'height': h, 'publisher': pubs[0] if pubs else None})

print(f'Sections with ID and height: {len(results)}')
for r in results[:15]:
    print(f"ID: {r['id']}, Height: {r['height']}, Pub: {r['publisher']}")

